import re

def tokenize(text):
    """Lower-case words and numbers; punctuation is dropped."""
    return re.findall(r"[a-z0-9]+", text.lower())

import math

def bm25_scores(query, index, doc_lens, k1=1.2, b=0.75):
    N = len(doc_lens)
    avgdl = sum(doc_lens.values()) / N
    scores = {}
    for word in tokenize(query):
        postings = index.get(word, {})
        n = len(postings)
        if n == 0:
            continue
        idf = math.log(1 + (N - n + 0.5) / (n + 0.5))
        for doc, f in postings.items():
            norm = k1 * (1 - b + b * doc_lens[doc] / avgdl)
            scores[doc] = scores.get(doc, 0.0) + idf * f * (k1 + 1) / (f + norm)
    return scores

