import re

def tokenize(text):
    """Lower-case words and numbers; punctuation is dropped."""
    return re.findall(r"[a-z0-9]+", text.lower())
import math

def build_index(docs):
    index = {}
    for doc_id, text in docs.items():
        for word in tokenize(text):
            postings = index.setdefault(word, {})
            postings[doc_id] = postings.get(doc_id, 0) + 1
    return index

import math

def bm25_scores(query, index, doc_lens, k1=1.2, b=0.75):
    N = len(doc_lens)
    avgdl = sum(doc_lens.values()) / N
    scores = {}
    for word in tokenize(query):
        postings = index.get(word, {})
        n = len(postings)
        if n == 0:
            continue
        idf = math.log(1 + (N - n + 0.5) / (n + 0.5))
        for doc, f in postings.items():
            norm = k1 * (1 - b + b * doc_lens[doc] / avgdl)
            scores[doc] = scores.get(doc, 0.0) + idf * f * (k1 + 1) / (f + norm)
    return scores

DOCS = {
    "d1": "How to request a refund for an order.",
    "d2": "Error E1047 means the refund could not be processed. Retry the refund later.",
    "d3": "Shipping times for international orders.",
    "d4": "Refund policy: refunds are issued within seven days. Refund requests need an order number.",
}

def search(query, docs, k=2):
    index = build_index(docs)
    doc_lens = {d: len(tokenize(t)) for d, t in docs.items()}
    scores = bm25_scores(query, index, doc_lens)
    return sorted(scores, key=lambda d: (-scores[d], d))[:k]
